+# These IDs are part of the Nemotron 6 MoE tokenizer/chat-template contract.
+# Keep them centralized so a tokenizer revision updates masking in one place.
+_NEMOTRON6_MOE_MESSAGE_START_TOKEN_ID = 10
+_NEMOTRON6_MOE_MESSAGE_END_TOKEN_ID = 11
+_NEMOTRON6_MOE_TOOL_RESPONSE_TOKEN_ID = 16
+_NEMOTRON6_MOE_LINE_BREAK_TOKEN_ID = 1010
+_NEMOTRON6_MOE_ASSISTANT_ROLE_TOKEN_IDS = (1503, 19464)
+_NEMOTRON6_MOE_USER_ROLE_TOKEN_ID = 3263
+_NEMOTRON6_MOE_TOKENIZER_CONTRACT = {
+    (_NEMOTRON6_MOE_MESSAGE_START_TOKEN_ID,): "<|im_start|>",
+    (_NEMOTRON6_MOE_MESSAGE_END_TOKEN_ID,): "<|im_end|>",
+    (_NEMOTRON6_MOE_TOOL_RESPONSE_TOKEN_ID,): "<tool_response>",
+    (_NEMOTRON6_MOE_LINE_BREAK_TOKEN_ID,): "
",
+    _NEMOTRON6_MOE_ASSISTANT_ROLE_TOKEN_IDS: "assistant",
+    (_NEMOTRON6_MOE_USER_ROLE_TOKEN_ID,): "user",
+}
+
+
+def _build_nemotron6_moe_native_tool_boundary_mask(conversation: List[Dict]) -> np.ndarray:
+    """Mark rendered user boundaries that originate from native tool turns."""
+    boundary_mask: List[bool] = []
+    previous_role: Optional[str] = None
+    for turn in conversation:
+        role = turn["role"]
+        if role == "user":
+            boundary_mask.append(False)
+        elif role == "tool" and previous_role != "tool":
+            # The Nemotron chat template coalesces consecutive tool turns into
+            # one rendered user block.
+            boundary_mask.append(True)
+        previous_role = role
+
+    return np.asarray(boundary_mask, dtype=bool)
+
+
+def _find_nemotron6_moe_assistant_indices(
+    tokens: np.ndarray,
+    prompt_format: str,
+    train_only_on_last_assistant_turn: bool,
+    has_nonempty_thinking_trace: bool,
+    tool_response_as_turn_boundary: bool,
+    native_tool_boundary_mask: np.ndarray,
+) -> np.ndarray:
+    """Find assistant turns selected by the Nemotron 6 MoE loss-mask policy."""
+    if prompt_format != "nemotron6-moe":
+        raise ValueError(
+            "Nemotron 6 MoE assistant masking only supports "
+            f"prompt_format='nemotron6-moe'; got {prompt_format!r}"
+        )
+
+    pattern_matches = np.where(
+        (tokens[:-2] == _NEMOTRON6_MOE_MESSAGE_START_TOKEN_ID)
+        & (tokens[1:-1] == _NEMOTRON6_MOE_ASSISTANT_ROLE_TOKEN_IDS[0])
+        & (tokens[2:] == _NEMOTRON6_MOE_ASSISTANT_ROLE_TOKEN_IDS[1])
+    )[0]
+    assistant_idx = pattern_matches + 1
+
+    if not train_only_on_last_assistant_turn:
+        return assistant_idx
+
+    use_native_tool_boundaries = tool_response_as_turn_boundary and bool(
+        np.any(native_tool_boundary_mask)
+    )
+
+    # Preserve the legacy heuristic: user turns starting with the
+    # <tool_response> token are excluded from ordinary user boundaries.
+    user_start_positions = np.where(
+        (tokens[:-1] == _NEMOTRON6_MOE_MESSAGE_START_TOKEN_ID)
+        & (tokens[1:] == _NEMOTRON6_MOE_USER_ROLE_TOKEN_ID)
+    )[0]
+    if len(user_start_positions) == 0:
+        if use_native_tool_boundaries:
+            raise ValueError("native tool responses did not render as user boundaries")
+        return assistant_idx
+
+    legacy_tool_response_mask = np.zeros_like(user_start_positions, dtype=bool)
+    valid_tool_check = user_start_positions + 3 < len(tokens)
+    tool_check_positions = user_start_positions[valid_tool_check]
+    legacy_tool_response_mask[valid_tool_check] = (
+        tokens[tool_check_positions + 2] == _NEMOTRON6_MOE_LINE_BREAK_TOKEN_ID
+    ) & (tokens[tool_check_positions + 3] == _NEMOTRON6_MOE_TOOL_RESPONSE_TOKEN_ID)
+
+    if use_native_tool_boundaries and len(native_tool_boundary_mask) != len(user_start_positions):
+        raise ValueError("tool-response roles do not match rendered user-turn boundaries")
+
+    if not has_nonempty_thinking_trace and not use_native_tool_boundaries:
+        return assistant_idx
+
+    boundary_mask = (
+        ~legacy_tool_response_mask
+        if has_nonempty_thinking_trace
+        else np.zeros_like(user_start_positions, dtype=bool)
+    )
+    if use_native_tool_boundaries:
+        boundary_mask |= native_tool_boundary_mask
+    boundary_positions = user_start_positions[boundary_mask]
+    if len(boundary_positions) == 0:
+        return assistant_idx
+
+    return assistant_idx[assistant_idx > boundary_positions[-1]]
+
